using System.Windows.Input; using Reforged.App.Commands; using Reforged.App.Models; using Reforged.App.Services;
namespace Reforged.App.ViewModels;
public sealed class HostViewModel : ViewModelBase
{
    private readonly IReforgedHostController _host; private readonly IHostCleanupScheduler _cleanup; private readonly IApplicationSettingsService _settings; private string _bindAddress="127.0.0.1"; private int _port=4000; private int _maximumSessions=64; private string _selectedWorld="classic";
    public string BindAddress{get=>_bindAddress;set{if(Set(ref _bindAddress,value))SyncOptions();}} public int Port{get=>_port;set{if(Set(ref _port,value))SyncOptions();}} public int MaximumSessions{get=>_maximumSessions;set{if(Set(ref _maximumSessions,value))SyncOptions();}} public string SelectedWorld{get=>_selectedWorld;set{if(Set(ref _selectedWorld,value))SyncOptions();}}
    public string State=>_host.State.ToString(); public string Status=>_host.StatusMessage; public int ConnectedSessions=>_host.ConnectedSessionCount;
    public HostCleanupSchedule Cleanup=>_settings.Current.HostCleanup; public string CleanupState=>_cleanup.StatusMessage; public DateTimeOffset? NextCleanup=>_cleanup.NextCleanupAt;
    public ICommand StartCommand{get;} public ICommand StopCommand{get;} public ICommand RestartCommand{get;} public ICommand SaveCleanupCommand{get;} public ICommand RunCleanupNowCommand{get;} public ICommand PostponeCleanupCommand{get;} public ICommand CancelCleanupCommand{get;}
    public HostViewModel(IReforgedHostController host,IHostCleanupScheduler cleanup,IApplicationSettingsService settings){_host=host;_cleanup=cleanup;_settings=settings;_selectedWorld=settings.Current.DefaultWorld;StartCommand=new AsyncRelayCommand(()=>_host.StartAsync(Options(),CancellationToken.None));StopCommand=new AsyncRelayCommand(()=>_host.StopAsync(CancellationToken.None));RestartCommand=new AsyncRelayCommand(()=>_host.RestartAsync(Options(),CancellationToken.None));SaveCleanupCommand=new AsyncRelayCommand(()=>_cleanup.UpdateScheduleAsync(Cleanup,CancellationToken.None));RunCleanupNowCommand=new AsyncRelayCommand(()=>_cleanup.RunCleanupNowAsync(CancellationToken.None));PostponeCleanupCommand=new AsyncRelayCommand(()=>_cleanup.PostponeAsync(TimeSpan.FromMinutes(30),CancellationToken.None));CancelCleanupCommand=new AsyncRelayCommand(()=>_cleanup.CancelPendingCleanupAsync(CancellationToken.None));_host.StateChanged+=(_,_)=>{Raise(nameof(State));Raise(nameof(Status));Raise(nameof(ConnectedSessions));};_cleanup.StateChanged+=(_,_)=>{Raise(nameof(CleanupState));Raise(nameof(NextCleanup));Raise(nameof(Cleanup));};SyncOptions();}
    private HostLaunchOptions Options()=>new(AppContext.BaseDirectory,BindAddress,Port,MaximumSessions,SelectedWorld); private void SyncOptions()=>_cleanup.UpdateLaunchOptions(Options());
}
